/**
 * Closed opportunities (/opportunity/<slug>) — notices whose response deadline passed within the
 * last 24 months. Each page states "Closed — responses were due <date>" and links to related open
 * notices. Generated by src/lib/seo/sitemap-sections.ts; listed in the sitemap index.
 */
import { renderUrlset, sitemapResponse, sitemapFailure } from '@/lib/seo/sitemap-xml';
import { closedOpportunityEntries } from '@/lib/seo/sitemap-sections';

// Rendered per request, cached at the CDN (s-maxage 6h + 1 day stale-while-revalidate), so a
// read failure answers 503 instead of being frozen into a build artifact.
export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    return sitemapResponse(renderUrlset(await closedOpportunityEntries()));
  } catch (err) {
    return sitemapFailure('opportunities-closed', err);
  }
}
